import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { positionLocal, mix, vec3, color, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, DirectionalLight, AmbientLight, PointLight, Color, DoubleSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#16161d', paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }]
  };
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }];
  const topHex = stops[0].hex;
  const botHex = stops[stops.length - 1].hex;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = items.find((i) => i.role === 'kicker');
  const brandItems = items.filter((i) => i.role === 'brand-mark');

  const brandNames = brandItems.length
    ? brandItems.map((i) => i.text)
    : ['HODINKEE', 'MONOCLE', 'WALLPAPER', 'ESQUIRE', 'WIRED', 'FINANCIAL TIMES'];

  const root = new Group();
  root.name = 'brand-mark-wall';

  const timelines = [];
  const disposables = [];
  const handlerTiles = [];

  // ---- Backdrop stage plane (vertical gradient) ----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const bTop = color(new Color(topHex));
  const bBot = color(new Color(botHex));
  const gy = positionLocal.y.mul(float(1 / 6)).add(float(0.5)).clamp(0, 1);
  backdropMat.colorNode = mix(bBot, bTop, gy);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- Lighting (rim/accent added node-locally) ----
  const ambient = new AmbientLight(0xffffff, 0.5);
  root.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.15);
  // 35deg elevation raking key
  key.position.set(-2.5, 2.0, 3.2);
  root.add(key);

  const rim = new DirectionalLight(new Color(colors.accent), 0.7);
  rim.position.set(3.0, -1.0, -1.5);
  root.add(rim);

  const fill = new PointLight(0xffffff, 0.35, 20);
  fill.position.set(0, 0, 4);
  root.add(fill);

  // ---- Tile grid ----
  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;
  const cols = 3;
  const rows = 2;
  const gridW = cols * tileW + (cols - 1) * gap; // 3.5
  const gridH = rows * tileH + (rows - 1) * gap; // 1.49
  const startX = -gridW / 2 + tileW / 2;
  const startY = gridH / 2 - tileH / 2;

  const tileGeo = new BoxGeometry(tileW, tileH, 0.06);
  disposables.push(tileGeo);

  const cTop = new Color(topHex);
  const cBot = new Color(botHex);

  const tiles = [];
  const orderIndex = []; // top row left-to-right first

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const name = brandNames[idx] ?? '';

      const tileGroup = new Group();
      tileGroup.position.set(startX + c * (tileW + gap), startY - r * (tileH + gap), 0);

      const mat = new MeshStandardNodeMaterial();
      // vertical albedo ramp
      const vy = positionLocal.y.mul(float(1 / tileH)).add(float(0.5)).clamp(0, 1);
      mat.colorNode = mix(color(cBot), color(cTop), vy);
      mat.roughness = 0.55;
      mat.metalness = 0.5;
      mat.clearcoat = 0.2;
      mat.clearcoatRoughness = 0.4;
      disposables.push(mat);

      const tile = new Mesh(tileGeo, mat);
      tileGroup.add(tile);

      // wordmark text flat monochrome
      const label = ctx.fontAtlas.createText(name, {
        fontSize: 42,
        color: colors.paper,
        align: 'center',
        letterSpacingPx: 3
      });
      label.position.set(0, 0, 0.045);
      // scale label into tile — assume createText returns px-scaled; nudge scale down
      label.scale.setScalar(0.0045);
      if (label.material) {
        label.material.transparent = true;
        label.material.opacity = 0.78;
      }
      label.traverse((o) => {
        if (o.material) { o.material.transparent = true; o.material.opacity = 0.78; }
      });
      tileGroup.add(label);

      // initial mount state
      tileGroup.position.y -= 0.2;
      tileGroup.userData._baseY = startY - r * (tileH + gap);
      mat.opacity = 0;
      mat.transparent = true;

      root.add(tileGroup);

      tiles.push({ group: tileGroup, mat, label, name });
      // stagger order: top row left-to-right, then bottom
      orderIndex.push(idx);
    }
  }

  // ---- Kicker ----
  if (kickerItem || true) {
    const kickerText = kickerItem?.text ?? 'AS FEATURED IN';
    const kicker = ctx.fontAtlas.createText(kickerText, {
      fontSize: 30,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 4
    });
    kicker.scale.setScalar(0.0045);
    kicker.position.set(0, gridH / 2 + 0.3, 0.05);
    kicker.traverse((o) => {
      if (o.material) { o.material.transparent = true; o.material.opacity = 0.85; }
    });
    root.add(kicker);
  }

  // ---- Mount animation: stagger-cards fade-up, top row first ----
  const tl = gsap.timeline();
  tiles.forEach((t, i) => {
    tl.to(t.group.position, {
      y: t.group.userData._baseY,
      duration: 0.5,
      ease: 'power2.out'
    }, i * 0.08);
    tl.to(t.mat, {
      opacity: 1,
      duration: 0.5,
      ease: 'power2.out'
    }, i * 0.08);
  });
  timelines.push(tl);

  // key light rake sweep as tiles settle
  const rakeTl = gsap.timeline();
  rakeTl.fromTo(key.position, { x: -3.6 }, { x: -2.5, duration: 1.4, ease: 'power3.out' }, 0);
  timelines.push(rakeTl);

  // ---- Hover handlers per tile ----
  function setTileHover(t, on) {
    gsap.to(t.group.position, {
      z: on ? 0.05 : 0,
      duration: 0.16,
      ease: 'power2.out'
    });
    const targetOpacity = on ? 1.0 : 0.78;
    t.label.traverse((o) => {
      if (o.material) {
        gsap.to(o.material, { opacity: targetOpacity, duration: 0.16, ease: 'power2.out' });
      }
    });
  }

  root.userData.handlers = {
    hover: (payload) => {
      const hitName = payload?.name || payload?.object?.name;
      tiles.forEach((t) => setTileHover(t, false));
      const found = tiles.find((t) => t.group === (payload?.object || null) || t.name === hitName);
      if (found) setTileHover(found, true);
    },
    pointerover: (payload) => {
      const found = tiles.find((t) => t.name === (payload?.name));
      if (found) setTileHover(found, true);
    },
    pointerout: () => {
      tiles.forEach((t) => setTileHover(t, false));
    }
  };

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    gsap.killTweensOf(tiles.map((t) => t.group.position));
    disposables.forEach((d) => { try { d.dispose(); } catch (e) {} });
    root.traverse((o) => {
      if (o.geometry && o.geometry.dispose) { try { o.geometry.dispose(); } catch (e) {} }
      if (o.material) {
        const m = Array.isArray(o.material) ? o.material : [o.material];
        m.forEach((mm) => { try { mm.dispose(); } catch (e) {} });
      }
    });
  };

  return root;
}
